#pragma once
/* The Japanese voices for the US version, built where there is no Python (Android): the same
 * SPJ and DAJ folders as tools/voice/build_jp_voices.py writes, from the player's two copies, with
 * the mapping that script derived from them as tables (voice_map.c, generated by its --emit-c). */
#include <stddef.h>
#include <stdint.h>

#include "voice_map_sizes.h"

#define VM_KEEP 255   /* VM_COUNT: the US clip stays */

extern const char *const VM_US_BANK[VM_US_BANKS];   /* SPH file names; the last two: cutscene tracks */
extern const uint16_t VM_US_CLIPS[VM_US_BANKS];
extern const char *const VM_JP_BANK[VM_JP_BANKS];
extern const uint16_t VM_JP_CLIPS[VM_JP_BANKS];
extern const uint16_t VM_FIRST[VM_CLIPS];
extern const uint8_t VM_COUNT[VM_CLIPS];
extern const uint32_t VM_SRC[VM_SRCS];

/* us_dir\SPJ holds every bank voice.c loads */
int voice_built(const char *us_dir);

/* builds us_dir\SPJ and us_dir\DAJ from the Japanese version in jp_dir; 1 = done, else msg says
   what is wrong (and nothing half-built is left in SPJ). *progress goes 0..1 (may be NULL). */
int voice_build_jp(const char *us_dir, const char *jp_dir, char *msg, size_t n, volatile float *progress);
